<?php
require __DIR__.'/common.php'; admin_require_login(); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm']??'');$q=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$hash=$q->fetchColumn();if(!$hash||!password_verify($old,$hash))$msg='گذرواژه فعلی صحیح نیست.';elseif(strlen($new)<12)$msg='گذرواژه جدید باید حداقل ۱۲ کاراکتر باشد.';elseif($new!==$confirm)$msg='تکرار گذرواژه مطابقت ندارد.';else{$q=$pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));$_SESSION['last_activity']=time();$msg='گذرواژه با موفقیت تغییر کرد.';}}
